/**
 * PreToolUse hook: blocks manual edits to generated files.
 * CHANGELOG.md is written by changesets, pnpm-lock.yaml by pnpm — hand edits either
 * get overwritten on the next release or corrupt the lockfile.
 */
import { readFileSync } from 'node:fs';

let input = {};
try {
  input = JSON.parse(readFileSync(0, 'utf8'));
} catch {
  process.exit(0);
}

const file = input?.tool_input?.file_path ?? '';
const blocked = [
  { pattern: /(^|\/)pnpm-lock\.yaml$/, reason: 'pnpm-lock.yaml is generated — run pnpm install instead.' },
  {
    pattern: /(^|\/)CHANGELOG\.md$/,
    reason: 'CHANGELOG.md is generated by changesets — add a changeset (pnpm changeset) instead.',
  },
];

for (const { pattern, reason } of blocked) {
  if (pattern.test(file)) {
    console.error(reason);
    process.exit(2);
  }
}
